examples.code:
// Equals
var statusFilter = new FilterDefinition
{
    Column = "Status",
    Operator = "eq",
    Value = "Active"
};

// Contains (text search)
var nameFilter = new FilterDefinition
{
    Column = "Name",
    Operator = "contains",
    Value = "john"
};

// Greater than
var ageFilter = new FilterDefinition
{
    Column = "Age",
    Operator = "gt",
    Value = 18
};

// In list
var categoryFilter = new FilterDefinition
{
    Column = "Category",
    Operator = "in",
    Value = new[] { "A", "B", "C" }
};
